package dev.podjs.runtime;

import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;
import org.json.*;
import android.util.Base64;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import static org.junit.Assert.*;

/** C7 F2/N1: one guest run under a caller-chosen memory limit. Local AES-GCM
 * goes to the product PodDeviceServices (256 KiB per call); no bypass. The synthetic
 * fixture is generated by the loopback test server and read from an app-private
 * file; no account material is compiled into the APK. The outcome (success or
 * the runtime failure code) is recorded, not asserted, so limits can be probed. */
public final class C7MemoryIntegrationTest {
 private File root;
 private JSONObject fixture;
 private PrivateKey signer;
 private SQLiteDatabase sql;
 private PodDeviceServices device;
 private int port;
 private long peakHwmKiB=0;
 private final List<JSONObject> events=new ArrayList<>();
 private static byte[] decode(String s){return Base64.decode(s,s.indexOf('-')>=0||s.indexOf('_')>=0?Base64.URL_SAFE:Base64.DEFAULT);}
 private static String encode(byte[] b){return Base64.encodeToString(b,Base64.NO_WRAP);}
 private static void delete(File f){File[] c=f.listFiles();if(c!=null)for(File x:c)delete(x);f.delete();}
 private static long status(String key){try{for(String line:Files.readAllLines(new File("/proc/self/status").toPath()))if(line.startsWith(key+":"))return Long.parseLong(line.replaceAll("[^0-9]",""));}catch(Exception ignored){}return -1;}
 private JSONArray query(JSONObject args)throws Exception {
  JSONArray p=args.optJSONArray("params");JSONArray rows=new JSONArray();try(Cursor c=sql.rawQueryWithFactory((database,driver,editTable,query)->{if(p!=null)for(int i=0;i<p.length();i++){Object value=p.opt(i);if(value==null||value==JSONObject.NULL)query.bindNull(i+1);else if(value instanceof Double||value instanceof Float)query.bindDouble(i+1,((Number)value).doubleValue());else if(value instanceof Number)query.bindLong(i+1,((Number)value).longValue());else query.bindString(i+1,String.valueOf(value));}return new android.database.sqlite.SQLiteCursor(driver,editTable,query);},args.getString("sql"),null,null)){while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++){Object v=JSONObject.NULL;switch(c.getType(i)){case Cursor.FIELD_TYPE_INTEGER:v=c.getLong(i);break;case Cursor.FIELD_TYPE_FLOAT:v=c.getDouble(i);break;case Cursor.FIELD_TYPE_STRING:v=c.getString(i);break;}row.put(c.getColumnName(i),v);}rows.put(row);}}return rows;
 }
 private Object http(JSONObject args)throws Exception {
  URL url=new URL(args.getString("url"));if(!url.getHost().equals("127.0.0.1")||url.getPort()!=port)throw new SecurityException();
  HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(60000);c.setRequestMethod(args.getString("method"));JSONObject h=args.getJSONObject("headers");Iterator<String> names=h.keys();while(names.hasNext()){String n=names.next();c.setRequestProperty(n,h.getString(n));}
  try{if(!args.isNull("body")){byte[] b=decode(args.getString("body"));c.setDoOutput(true);c.setFixedLengthStreamingMode(b.length);try(OutputStream out=c.getOutputStream()){out.write(b);}}
   int status=c.getResponseCode();ByteArrayOutputStream bytes=new ByteArrayOutputStream();InputStream stream=status>=400?c.getErrorStream():c.getInputStream();if(stream!=null)try(InputStream in=stream){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;){if(bytes.size()+n>1048576)throw new IOException();bytes.write(b,0,n);}}
   JSONObject headers=new JSONObject();for(Map.Entry<String,List<String>> entry:c.getHeaderFields().entrySet())if(entry.getKey()!=null)headers.put(entry.getKey().toLowerCase(Locale.ROOT),entry.getValue().get(0));
   return new JSONObject().put("status",status).put("headers",headers).put("body",encode(bytes.toByteArray()));
  }finally{c.disconnect();}
 }
 private Object dispatch(String method,JSONObject args)throws Exception {
  switch(method){
   case "http":return http(args);
   case "result":events.add(new JSONObject(args.toString()).put("hwmKiB",status("VmHWM")));return JSONObject.NULL;
   case "sql.query":return query(args);
   case "sql.transaction":sql.beginTransaction();try{JSONArray statements=args.getJSONArray("statements");for(int i=0;i<statements.length();i++){JSONObject s=statements.getJSONObject(i);if(s.has("program")){PodSqlProgram.execute(sql,s.getJSONObject("program"),new android.os.CancellationSignal());continue;}JSONArray p=s.optJSONArray("params");Object[] values=new Object[p==null?0:p.length()];for(int j=0;j<values.length;j++)values[j]=p.isNull(j)?null:p.get(j);sql.execSQL(s.getString("sql"),values);}if(!args.optBoolean("validateOnly",false)&&!PodSqlProgram.validateOnly(statements))sql.setTransactionSuccessful();}finally{sql.endTransaction();}return JSONObject.NULL;
   case "crypto.v2.sign":return new JSONObject().put("signatureBase64",encode(PodSyncV2Crypto.sign(signer,decode(args.getString("dataBase64")))));
   case "crypto.v2.signingKey":return new JSONObject().put("publicKeySec1",encode(decode(fixture.getString("publicKeyBase64Url"))));
   case "secure.get":return device.execute(method,args).opt("value");
   default:if(!method.startsWith("crypto.")&&!method.equals("secure.compareAndSet"))throw new SecurityException();return device.execute(method,args);
  }
 }
 @Test public void probe()throws Exception {
  File base=new File(InstrumentationRegistry.getInstrumentation().getTargetContext().getFilesDir(),"syncv2-c7-memory");
  fixture=new JSONObject(new String(Files.readAllBytes(new File(base,"fixture.json").toPath()),StandardCharsets.UTF_8));assertTrue(fixture.getBoolean("syntheticOnly"));
  port=fixture.getInt("port");int memoryBytes=fixture.getInt("memoryBytes");String pem=fixture.getString("privateKeyPkcs8Pem").replaceAll("-----[^-]+-----","").replaceAll("\\s","");signer=KeyFactory.getInstance("EC").generatePrivate(new PKCS8EncodedKeySpec(decode(pem)));
  String runId=UUID.randomUUID().toString().replace("-","");fixture.put("runId",runId).put("baseUrl","http://127.0.0.1:"+port);fixture.remove("privateKeyPkcs8Pem");
  String source=new String(Files.readAllBytes(new File(base,"guest.js").toPath()),StandardCharsets.UTF_8);
  root=new File(base,"run");delete(root);new File(base,"result.json").delete();assertTrue(root.mkdirs());sql=SQLiteDatabase.openOrCreateDatabase(new File(root,"projection.sqlite"),null);
  File fileRoot=new File(root,"owned-files");fileRoot.mkdirs();device=new PodDeviceServices(fileRoot,()->new SecretKeySpec(new byte[32],"AES"));
  long startRss=status("VmRSS"),startHwm=status("VmHWM"),started=System.currentTimeMillis();JSONObject result=new JSONObject();
  ExecutorService executor=Executors.newSingleThreadExecutor();try(PodBackgroundRun run=new PodBackgroundRun("watch-c7-memory","integration",source,300000,memoryBytes,fixture,new String[]{"cloud.host"})){
   Future<JSONObject> outcome=executor.submit(run::run);
   while(!outcome.isDone()){peakHwmKiB=Math.max(peakHwmKiB,status("VmHWM"));JSONObject r=run.waitRequest(50);if(r==null)continue;JSONObject a=r.getJSONObject("args");JSONObject reply=new JSONObject().put("id",r.getLong("id"));try{reply.put("ok",true).put("value",dispatch(a.getString("method"),a.getJSONObject("args")));}catch(Exception error){reply.put("ok",false).put("code","integration_host_"+error.getClass().getSimpleName());events.add(new JSONObject().put("event","host_error").put("method",a.getString("method")).put("error",error.getClass().getSimpleName()));}try{run.reply(reply);}catch(IllegalArgumentException tooLarge){events.add(new JSONObject().put("event","host_error").put("method",a.getString("method")).put("error","reply_too_large"));run.reply(new JSONObject().put("id",r.getLong("id")).put("ok",false).put("code","integration_reply_too_large"));}}
   result=outcome.get(10,TimeUnit.SECONDS);
  }finally{executor.shutdownNow();device.close();sql.close();}
  peakHwmKiB=Math.max(peakHwmKiB,status("VmHWM"));
  JSONObject out=new JSONObject().put("mode",fixture.getString("mode")).put("notes",fixture.getInt("notes")).put("guestMemoryLimitBytes",memoryBytes).put("status",result.optString("status")).put("code",result.optString("code")).put("millis",System.currentTimeMillis()-started).put("startRssKiB",startRss).put("startHwmKiB",startHwm).put("peakHwmKiB",peakHwmKiB).put("events",new JSONArray(events));
  Files.write(new File(base,"result.json").toPath(),out.toString(2).getBytes(StandardCharsets.UTF_8));
 }
}
